(1073250, 129815, 28141, '<td valign="top">Cute picture, but the border is extremely distracting.</td>', 'Cute picture, but the border is extremely distracting.', '2004-12-22 01:33:19.000000', NULL, 1),
(1073251, 129164, 28141, '<td valign="top">The border is distracting and the image too small.  Getting rid of the border would have allowed you to submit a larger version of the image, with more detail.</td>', 'The border is distracting and the image too small.  Getting rid of the border would have allowed you to submit a larger version of the image, with more detail.', '2004-12-22 01:34:27.000000', NULL, 1),
(1073263, 129164, 19952, '<td valign="top">I''m one of the people who actually like borders, but I don''t think this one helps the shot. It''s such a nice picture that making it just that much smaller with a frame is a detraction. Still, the photo itself is excellent - one of the best in this challenge.</td>', 'I''m one of the people who actually like borders, but I don''t think this one helps the shot. It''s such a nice picture that making it just that much smaller with a frame is a detraction. Still, the photo itself is excellent - one of the best in this challenge.', '2004-12-22 01:46:03.000000', NULL, 1),
(1073267, 129906, 19952, '<td valign="top">This is a really great shot for this challenge. I wish it were a little brighter, but it still came out great. Nice job!</td>', 'This is a really great shot for this challenge. I wish it were a little brighter, but it still came out great. Nice job!', '2004-12-22 01:52:54.000000', NULL, 1),
(1073271, 129967, 16648, '<td valign="top">The thumbnail caught my eye. I like the composition, color. The subject is NOT in focus though. And the tall grass pieces on the left should have been moved for the shot, or cropped out.</td>', 'The thumbnail caught my eye. I like the composition, color. The subject is NOT in focus though. And the tall grass pieces on the left should have been moved for the shot, or cropped out.', '2004-12-22 01:58:11.000000', NULL, 1),
(1073272, 129640, 16648, '<td valign="top">Grainy and out of focus. Technically, a 1 or less.</td>', 'Grainy and out of focus. Technically, a 1 or less.', '2004-12-22 01:58:43.000000', NULL, 1),
(1073273, 129725, 16648, '<td valign="top">Are these pets? The composition is too centered.</td>', 'Are these pets? The composition is too centered.', '2004-12-22 01:59:24.000000', NULL, 1),
(1073274, 128960, 16648, '<td valign="top">The human is sharp, the canine blurry.</td>', 'The human is sharp, the canine blurry.', '2004-12-22 02:00:05.000000', NULL, 1),
(1073275, 129969, 16648, '<td valign="top">Too dark for me.</td>', 'Too dark for me.', '2004-12-22 02:00:18.000000', NULL, 1),
