(1077372, 129858, 27293, '<td valign="top">Awful flash kills everything in this shot. It could have been nice, but as it is it''s just a bad snapshot.</td>', 'Awful flash kills everything in this shot. It could have been nice, but as it is it''s just a bad snapshot.', '2004-12-25 23:07:27.000000', NULL, 1),
(1077373, 129796, 23456, '<td valign="top">Something different - I like it , Well done !</td>', 'Something different - I like it , Well done !', '2004-12-25 23:08:54.000000', NULL, 1),
(1077374, 129934, 27293, '<td valign="top">I suppose i would try a slightly different viewpoint here, so that the snake''s head isn''t right in fron of its body. Also the color of the guy''s face is somewhat unnatural.</td>', 'I suppose i would try a slightly different viewpoint here, so that the snake''s head isn''t right in fron of its body. Also the color of the guy''s face is somewhat unnatural.', '2004-12-25 23:08:57.000000', NULL, 1),
