(1077378, 129516, 27293, '<td valign="top">Not bad, but it seems a bit too tight, they don''t have enough breathing space here.</td>', 'Not bad, but it seems a bit too tight, they don''t have enough breathing space here.', '2004-12-25 23:13:35.000000', NULL, 1),
(1077380, 129833, 27293, '<td valign="top">Just terrible. Every aspect of this photo is bad, with the exception of the models, who are photogenic, just not presented well at all.</td>', 'Just terrible. Every aspect of this photo is bad, with the exception of the models, who are photogenic, just not presented well at all.', '2004-12-25 23:14:37.000000', NULL, 1),
